function normalizeCutsceneSkipThreshold(value) {
  const normalizedValue = typeof value === "string"
    ? value.replace(/[,_\s]/g, "")
    : value;
  const parsed = Number.parseFloat(normalizedValue);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return DEFAULT_CUTSCENE_SKIP_THRESHOLD;
  }

  return Math.floor(parsed);
}

function formatCutsceneSkipThreshold(value) {
  const normalized = normalizeCutsceneSkipThreshold(value);
  return normalized > 0 ? normalized.toLocaleString() : "0";
}

function shouldSkipCutsceneForRarity(rarity) {
  const threshold = normalizeCutsceneSkipThreshold(cutsceneSkipThreshold);
  if (threshold <= 0 || !rarity || typeof rarity !== "object") {
    return false;
  }

  const displayedOdds = getEffectiveSkipOddsForRarity(rarity);
  return Number.isFinite(displayedOdds) && displayedOdds < threshold;
}

function getCurrentTitleSkipRarityForClass(rarityClass) {
  const candidates = [currentRollRarityForTitleSkip, pendingCutsceneRarity];
  return candidates.find((candidate) => {
    return Boolean(
      candidate &&
      typeof candidate === "object" &&
      candidate.class === rarityClass
    );
  }) || null;
}

function shouldSkipTitleSaveForRarityClass(rarityClass) {
  const threshold = normalizeCutsceneSkipThreshold(titleSkipThreshold);
  if (threshold <= 0) {
    return false;
  }

  const rarity = getCurrentTitleSkipRarityForClass(rarityClass);
  if (!rarity) {
    return false;
  }

  const titleSkipOdds = getEffectiveSkipOddsForRarity(rarity);
  return Number.isFinite(titleSkipOdds) && titleSkipOdds < threshold;
}

function shouldPlayCutsceneForRarity(rarity) {
  return !shouldSkipCutsceneForRarity(rarity);
}

function setLegacyCutsceneFlags(value) {
  const shouldPlay = Boolean(value);
  skipCutscene1K = shouldPlay;
  skipCutscene10K = shouldPlay;
  skipCutscene100K = shouldPlay;
  skipCutscene1M = shouldPlay;
  skipCutsceneTranscendent = shouldPlay;
  skipCutsceneHalloween25 = shouldPlay;
  skipCutsceneOG = shouldPlay;
}

function syncCutsceneSkipStateForRarity(rarity) {
  setLegacyCutsceneFlags(shouldPlayCutsceneForRarity(rarity));
}

function updateCutsceneSkipThresholdDisplay() {
  const inputElement = byId("cutsceneSkipThresholdInput");
  if (inputElement) {
    inputElement.value = String(cutsceneSkipThreshold);
  }

  const statusElement = byId("cutsceneSkipThresholdStatus");
  if (!statusElement) {
    return;
  }

  if (cutsceneSkipThreshold <= 0) {
    statusElement.textContent = "Playing all cutscenes";
    return;
  }

  statusElement.textContent = `Skipping cutscenes below 1 in ${formatCutsceneSkipThreshold(cutsceneSkipThreshold)}`;
}

function updateTitleSkipThresholdDisplay() {
  const inputElement = byId("titleSkipThresholdInput");
  if (inputElement) {
    inputElement.value = String(titleSkipThreshold);
  }

  const statusElement = byId("titleSkipThresholdStatus");
  if (!statusElement) {
    return;
  }

  if (titleSkipThreshold <= 0) {
    statusElement.textContent = "Saving all rolled titles";
    return;
  }

  statusElement.textContent = `Auto-skipping titles below 1 in ${formatCutsceneSkipThreshold(titleSkipThreshold)}`;
}

const QUALIFYING_VAULT_BUCKETS = new Set(["under100k", "under1m", "transcendent", "special", "theDescended", "goodOldDays"]);
function normalizeRarityClassName(value) {
  const trimmed = typeof value === "string" ? value.trim() : value == null ? "" : String(value).trim();
  if (!trimmed) {
    return "";
  }

  return RARITY_CLASS_ALIASES[trimmed] || trimmed;
}

function isCommandGrantedInventoryRecord(item) {
  return Boolean(
    item &&
    typeof item === "object" &&
    (item.givenByCommand === true || item.source === "command")
  );
}

function normalizeInventoryRecord(raw) {
  if (raw == null) {
    return { record: null, mutated: raw !== undefined };
  }

  if (typeof raw === "string") {
    const title = raw.trim();
    if (!title) {
      return { record: null, mutated: true };
    }

    const rarityClass = inferRarityClassForInventoryTitle(title);

    const bucket = normalizeRarityBucket(rarityClass);
    const record = {
      title,
      rarityClass,
      qualifiesForVault: QUALIFYING_VAULT_BUCKETS.has(bucket),
    };
    if (bucket) {
      record.rarityBucket = bucket;
    }

    return { record, mutated: true };
  }

  if (typeof raw !== "object") {
    return { record: null, mutated: true };
  }

  const record = raw;
  let mutated = false;

  let title = "";
  if (typeof record.title === "string") {
    title = record.title.trim();
    if (title !== record.title) {
      record.title = title;
      mutated = true;
    }
  } else if (record.title != null) {
    title = String(record.title).trim();
    record.title = title;
    mutated = true;
  }

  if (!title) {
    return { record: null, mutated: true };
  }

  let rarityClass = "";
  if (typeof record.rarityClass === "string") {
    rarityClass = record.rarityClass.trim();
    if (rarityClass !== record.rarityClass) {
      mutated = true;
    }
  } else if (record.rarityClass != null) {
    rarityClass = String(record.rarityClass).trim();
    mutated = true;
  } else {
    rarityClass = "";
  }

  const inferredRarityClass = rarityClass || inferRarityClassForInventoryTitle(title);
  const normalizedRarityClass = normalizeRarityClassName(inferredRarityClass);
  if (record.rarityClass !== normalizedRarityClass) {
    record.rarityClass = normalizedRarityClass;
    mutated = true;
  }

  if (typeof record.rolledAt !== "number" || !Number.isFinite(record.rolledAt)) {
    if (Object.prototype.hasOwnProperty.call(record, "rolledAt")) {
      delete record.rolledAt;
      mutated = true;
    }
  }

  if (typeof record.luckValue === "number" && Number.isFinite(record.luckValue)) {
    const clamped = Math.max(0, record.luckValue);
    if (clamped !== record.luckValue) {
      record.luckValue = clamped;
      mutated = true;
    }
  } else if (Object.prototype.hasOwnProperty.call(record, "luckValue")) {
    delete record.luckValue;
    mutated = true;
  }

  if (record.givenByCommand === "true") {
    record.givenByCommand = true;
    mutated = true;
  } else if (record.givenByCommand !== true && Object.prototype.hasOwnProperty.call(record, "givenByCommand")) {
    delete record.givenByCommand;
    mutated = true;
  }

  if (record.source === "command") {
    if (record.givenByCommand !== true) {
      record.givenByCommand = true;
      mutated = true;
    }
    delete record.source;
    mutated = true;
  } else if (Object.prototype.hasOwnProperty.call(record, "source")) {
    delete record.source;
    mutated = true;
  }

  const bucket = normalizeRarityBucket(record.rarityClass);

  if (bucket) {
    if (record.rarityBucket !== bucket) {
      record.rarityBucket = bucket;
      mutated = true;
    }
  } else if (record.rarityBucket) {
    delete record.rarityBucket;
    mutated = true;
  }

  const qualifies = QUALIFYING_VAULT_BUCKETS.has(bucket);
  if (record.qualifiesForVault !== qualifies) {
    record.qualifiesForVault = qualifies;
    mutated = true;
  }

  if (typeof record.inventoryId !== "string" || !record.inventoryId.trim()) {
    record.inventoryId = generateInventoryRecordId();
    mutated = true;
  }

  return { record, mutated };
}

function normalizeInventoryRecords(records) {
  if (!Array.isArray(records)) {
    return { records: [], mutated: records != null };
  }

  const normalized = [];
  let mutated = false;

  records.forEach((raw) => {
    try {
      const { record, mutated: recordMutated } = normalizeInventoryRecord(raw);
      if (record) {
        normalized.push(record);
      } else {
        mutated = true;
      }

      if (recordMutated) {
        mutated = true;
      }
    } catch (error) {
      console.warn("Skipping inventory record that could not be migrated.", raw, error);
      mutated = true;
    }
  });

  return { records: normalized, mutated };
}

function getQualifyingInventoryCount(items = inventory) {
  if (!Array.isArray(items) || items.length === 0) {
    return 0;
  }

  return items.reduce((total, item) => {
    if (!item || typeof item !== "object") {
      return total;
    }

    if (typeof item.qualifiesForVault === "boolean") {
      return item.qualifiesForVault ? total + 1 : total;
    }

    const bucket = item.rarityBucket || normalizeRarityBucket(item.rarityClass);
    if (bucket && bucket !== item.rarityBucket) {
      item.rarityBucket = bucket;
    } else if (!bucket && item.rarityBucket) {
      delete item.rarityBucket;
    }

    const qualifies = QUALIFYING_VAULT_BUCKETS.has(bucket);
    item.qualifiesForVault = qualifies;
    return qualifies ? total + 1 : total;
  }, 0);
}

function createEmptyAchievementStats() {
  return {
    qualifyingInventoryCount: 0,
    inventoryTitleSet: new Set(),
    inventoryRarityClassSet: new Set(),
    eventBucketCounts: new Map(),
    totalEventTitleCount: 0,
    distinctEventBucketCount: 0,
  };
}

let latestAchievementStats = createEmptyAchievementStats();

function computeAchievementStats(items = inventory) {
  const qualifyingInventoryCount = getQualifyingInventoryCount(items);
  const inventoryTitleSet = new Set();
  const inventoryRarityClassSet = new Set();
  const eventBucketCounts = new Map();
  let totalEventTitleCount = 0;

  if (Array.isArray(items)) {
    items.forEach((item) => {
      if (!item || typeof item !== "object") {
        return;
      }

      if (typeof item.title === "string" && item.title) {
        inventoryTitleSet.add(item.title);
      }

      if (typeof item.rarityClass === "string" && item.rarityClass) {
        inventoryRarityClassSet.add(item.rarityClass.trim());
      }

      const bucket =
        (typeof item.rarityBucket === "string" && item.rarityBucket) ||
        normalizeRarityBucket(item.rarityClass);

      if (bucket && bucket.startsWith("event")) {
        totalEventTitleCount += 1;
        eventBucketCounts.set(bucket, (eventBucketCounts.get(bucket) || 0) + 1);
      }
    });
  }

  const stats = {
    qualifyingInventoryCount,
    inventoryTitleSet,
    inventoryRarityClassSet,
    eventBucketCounts,
    totalEventTitleCount,
    distinctEventBucketCount: eventBucketCounts.size,
  };

  latestAchievementStats = stats;
  return stats;
}

