function selectTitle(rarity) {
  const titles = Array.isArray(rarity?.titles) && rarity.titles.length
    ? rarity.titles
    : [rarity?.type || "Unknown Title"];
  return titles[Math.floor(Math.random() * titles.length)];
}

function findMatchingSourceDelimiter(source, startIndex, openChar, closeChar) {
  if (typeof source !== "string" || source[startIndex] !== openChar) {
    return -1;
  }

  let depth = 0;
  let quote = "";
  let escaped = false;
  let lineComment = false;
  let blockComment = false;

  for (let index = startIndex; index < source.length; index += 1) {
    const char = source[index];
    const next = source[index + 1];

    if (lineComment) {
      if (char === "\n" || char === "\r") {
        lineComment = false;
      }
      continue;
    }

    if (blockComment) {
      if (char === "*" && next === "/") {
        blockComment = false;
        index += 1;
      }
      continue;
    }

    if (quote) {
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === quote) {
        quote = "";
      }
      continue;
    }

    if (char === "/" && next === "/") {
      lineComment = true;
      index += 1;
      continue;
    }

    if (char === "/" && next === "*") {
      blockComment = true;
      index += 1;
      continue;
    }

    if (char === "\"" || char === "'" || char === "`") {
      quote = char;
      continue;
    }

    if (char === openChar) {
      depth += 1;
      continue;
    }

    if (char === closeChar) {
      depth -= 1;
      if (depth === 0) {
        return index;
      }
    }
  }

  return -1;
}

function evaluateSourceLiteral(source) {
  try {
    return Function(`"use strict"; return (${source});`)();
  } catch (error) {
    console.warn("Unable to read dev rarity definitions.", error);
    return null;
  }
}

function isDevRarityDefinition(value) {
  return Boolean(
    value &&
    typeof value === "object" &&
    typeof value.type === "string" &&
    typeof value.class === "string"
  );
}

function isExcludedFromDevEverythingGrant(definition) {
  return Boolean(definition && definition.unobtainable);
}

function extractPrimaryRarityDefinitionsFromSource(source) {
  const markerIndex = source.indexOf("const rarities =");
  if (markerIndex < 0) {
    return [];
  }

  const arrayStart = source.indexOf("[", markerIndex);
  if (arrayStart < 0) {
    return [];
  }

  const arrayEnd = findMatchingSourceDelimiter(source, arrayStart, "[", "]");
  if (arrayEnd < 0) {
    return [];
  }

  const value = evaluateSourceLiteral(source.slice(arrayStart, arrayEnd + 1));
  return Array.isArray(value) ? value.filter(isDevRarityDefinition) : [];
}

function extractSpecialRarityDefinitionsFromSource(source) {
  const definitions = [];
  const specialPattern = /const\s+\w+Rarity\s*=\s*\{/g;
  let match = specialPattern.exec(source);

  while (match) {
    const objectStart = source.indexOf("{", match.index);
    const objectEnd = findMatchingSourceDelimiter(source, objectStart, "{", "}");

    if (objectStart >= 0 && objectEnd >= 0) {
      const value = evaluateSourceLiteral(source.slice(objectStart, objectEnd + 1));
      if (isDevRarityDefinition(value)) {
        definitions.push(value);
      }
      specialPattern.lastIndex = objectEnd + 1;
    }

    match = specialPattern.exec(source);
  }

  return definitions;
}

function getRarityDefinitionsForDevGrant() {
  if (cachedRarityDefinitionsForDevGrant) {
    return cachedRarityDefinitionsForDevGrant;
  }

  const cachedDefinitions =
    typeof globalThis !== "undefined" && Array.isArray(globalThis.__unnamedRngRarityDefinitions)
      ? globalThis.__unnamedRngRarityDefinitions
      : [];

  const source = typeof rollRarity === "function"
    ? Function.prototype.toString.call(rollRarity)
    : "";

  const definitions = [
    ...cachedDefinitions,
    ...extractPrimaryRarityDefinitionsFromSource(source),
    ...extractSpecialRarityDefinitionsFromSource(source),
    ...DESCENDED_TITLE_DEFINITIONS.map((definition) => ({
      type: definition.type,
      class: definition.class,
      titles: [definition.type],
    })),
  ];

  const seen = new Set();
  cachedRarityDefinitionsForDevGrant = definitions.filter((definition) => {
    if (!isDevRarityDefinition(definition)) {
      return false;
    }

    const key = `${definition.type}::${definition.class}`;
    if (seen.has(key)) {
      return false;
    }

    seen.add(key);
    return true;
  });

  return cachedRarityDefinitionsForDevGrant;
}

function addRarityDefinitionLookupEntry(map, key, definition) {
  const normalizedKey = normalizeDevLookupText(key);
  if (!normalizedKey || map.has(normalizedKey)) {
    return;
  }

  map.set(normalizedKey, definition);
}

function getRarityDefinitionLookupByTitle() {
  if (rarityDefinitionLookupByTitle) {
    return rarityDefinitionLookupByTitle;
  }

  const lookup = new Map();
  getRarityDefinitionsForDevGrant().forEach((definition) => {
    const titles = Array.isArray(definition.titles) && definition.titles.length
      ? definition.titles
      : [definition.type];

    addRarityDefinitionLookupEntry(lookup, definition.type, definition);
    addRarityDefinitionLookupEntry(lookup, getDevRarityDisplayName(definition), definition);
    titles.forEach((candidate) => addRarityDefinitionLookupEntry(lookup, candidate, definition));
  });

  rarityDefinitionLookupByTitle = lookup;
  return rarityDefinitionLookupByTitle;
}

function findRarityDefinitionForInventoryTitle(title) {
  const needle = normalizeDevLookupText(title);
  if (!needle) {
    return null;
  }

  return getRarityDefinitionLookupByTitle().get(needle) || null;
}

function inferRarityClassForInventoryTitle(title) {
  const definition = findRarityDefinitionForInventoryTitle(title);
  return normalizeRarityClassName(definition?.class || "");
}

function getAllDevTitleGrantRecords() {
  const existing = new Set(
    inventory
      .filter((item) => item && typeof item === "object")
      .map((item) => `${item.title}::${item.rarityClass}`)
  );
  const records = [];
  const rolledAt = typeof rollCount === "number" ? rollCount : 0;
  const luckValue = getCurrentLuckValue();

  const addGrantRecord = (title, rarityClass) => {
    if (typeof title !== "string" || !title.trim() || typeof rarityClass !== "string") {
      return;
    }

    const key = `${title.trim()}::${rarityClass.trim()}`;
    if (existing.has(key)) {
      return;
    }

    const { record } = normalizeInventoryRecord({
      title: title.trim(),
      rarityClass: rarityClass.trim(),
      rolledAt,
      luckValue,
      givenByCommand: true,
    });

    if (!record) {
      return;
    }

    existing.add(key);
    records.push(record);
  };

  getRarityDefinitionsForDevGrant().forEach((definition) => {
    if (isExcludedFromDevEverythingGrant(definition)) {
      return;
    }

    const titles = Array.isArray(definition.titles) && definition.titles.length
      ? definition.titles
      : [definition.type];

    titles.forEach((title) => addGrantRecord(title, definition.class));
    addGrantRecord(definition.type, definition.class);
  });

  ACHIEVEMENTS.forEach((achievement) => {
    if (
      achievement.requiredTitle &&
      achievement.requiredRarityClass &&
      achievement.requiredRarityClass !== "malvorynBgImg"
    ) {
      addGrantRecord(achievement.requiredTitle, achievement.requiredRarityClass);
    }

    if (
      Array.isArray(achievement.requiredTitles) &&
      achievement.requiredRarityClass &&
      achievement.requiredRarityClass !== "malvorynBgImg"
    ) {
      achievement.requiredTitles.forEach((title) => {
        addGrantRecord(title, achievement.requiredRarityClass);
      });
    }
  });

  return records;
}

function grantAllDevTitlesCommand() {
  const titleRecords = getAllDevTitleGrantRecords();
  if (titleRecords.length) {
    inventory = [...inventory, ...titleRecords];
    storage.set("inventory", inventory);
  }

  renderInventory();
  checkAchievements();
  updateAchievementsList();

  const summary = {
    titlesAdded: titleRecords.length,
  };

  console.info("Dev title grant applied.", summary);
  return summary;
}

function grantUnlimitedPotionsDevCommand() {
  POTION_DEFINITIONS.forEach((potion) => {
    if (!potion || !potion.id) {
      return;
    }

    unlimitedPotionIds.add(potion.id);
    if (!Number.isFinite(potionInventory[potion.id]) || potionInventory[potion.id] <= 0) {
      potionInventory[potion.id] = 1;
    }
  });
  savePotionInventory();
  saveUnlimitedPotionIds();

  renderPotionInventory();
  renderPotionCrafting();
  renderPotionTransactions();
  updateAutoRollAvailability();

  const summary = {
    potionsUnlimited: unlimitedPotionIds.size,
  };

  console.info("Dev unlimited potions applied.", summary);
  return summary;
}

function grantDevModeUnlockReward() {
  incrementRollCounts(1000);
  localStorage.setItem("rollCount", rollCount);
  localStorage.setItem("rollCount1", rollCount1);

  updateRollDisplays();
  updateAutoRollAvailability();

  const summary = {
    rollsAdded: 1000,
  };

  console.info("Dev mode unlock reward applied.", summary);
  return summary;
}

function getDevAchievementNameCandidates() {
  const names = new Set();

  ACHIEVEMENTS.forEach((achievement) => {
    if (achievement && typeof achievement.name === "string" && achievement.name.trim()) {
      names.add(achievement.name.trim());
    }
  });

  COLLECTOR_ACHIEVEMENTS.forEach((achievement) => {
    if (achievement && typeof achievement.name === "string" && achievement.name.trim()) {
      names.add(achievement.name.trim());
    }
  });

  $all("[data-name]").forEach((element) => {
    const name = element.getAttribute("data-name");
    if (typeof name === "string" && name.trim()) {
      names.add(name.trim());
    }
  });

  unlockedAchievementsCache.forEach((name) => {
    if (typeof name === "string" && name.trim()) {
      names.add(name.trim());
    }
  });

  return Array.from(names);
}

function findDevAchievementName(achievementName) {
  const requested = String(achievementName || "").trim();
  if (!requested) {
    return null;
  }

  const candidates = getDevAchievementNameCandidates();
  const exactMatch = candidates.find((name) => name === requested);
  if (exactMatch) {
    return exactMatch;
  }

  const lowerMatch = candidates.find((name) => name.toLowerCase() === requested.toLowerCase());
  if (lowerMatch) {
    return lowerMatch;
  }

  const normalizedRequested = normalizeDevLookupText(requested);
  return candidates.find((name) => normalizeDevLookupText(name) === normalizedRequested) || null;
}

function getDevAchievementArgument(tokens) {
  return tokens.slice(1).join(" ").trim();
}

function grantDevAchievementCommand(achievementName) {
  const resolvedName = findDevAchievementName(achievementName);
  if (!resolvedName) {
    return { ok: false, message: `Unknown achievement: ${achievementName}` };
  }

  const unlocked = getUnlockedAchievementsSnapshot();
  if (unlocked.has(resolvedName)) {
    return { ok: true, message: `${resolvedName} is already unlocked.` };
  }

  unlockAchievement(resolvedName, unlocked);
  updateAchievementsList();
  updateAutoRollAvailability();

  return { ok: true, message: `Unlocked achievement: ${resolvedName}.` };
}

function removeDevAchievementCommand(achievementName) {
  const resolvedName = findDevAchievementName(achievementName);
  if (!resolvedName) {
    return { ok: false, message: `Unknown achievement: ${achievementName}` };
  }

  const unlocked = getUnlockedAchievementsSnapshot();
  if (!unlocked.has(resolvedName)) {
    return { ok: true, message: `${resolvedName} is not unlocked.` };
  }

  unlocked.delete(resolvedName);
  persistUnlockedAchievements(unlocked);
  updateAchievementsList();
  updateAutoRollAvailability();

  return { ok: true, message: `Removed achievement: ${resolvedName}.` };
}

function grantAllDevAchievementsCommand() {
  const unlocked = getUnlockedAchievementsSnapshot();
  let added = 0;

  getDevAchievementNameCandidates().forEach((name) => {
    if (!unlocked.has(name)) {
      unlocked.add(name);
      added += 1;
    }
  });

  persistUnlockedAchievements(unlocked);
  updateAchievementsList();
  updateAutoRollAvailability();

  return {
    ok: true,
    message: `Unlocked ${added.toLocaleString("en-US")} achievement${added === 1 ? "" : "s"}.`,
  };
}

function normalizeDevLookupText(value) {
  return String(value || "")
    .replace(/\[[^\]]*\]/g, " ")
    .replace(/[^a-z0-9]+/gi, " ")
    .trim()
    .toLowerCase();
}

function getDevRarityDisplayName(definition) {
  return String(definition?.type || "").replace(/\s*\[[^\]]+\]\s*$/u, "").trim();
}

function findDevRarityDefinition(titleName) {
  const needle = normalizeDevLookupText(titleName);
  if (!needle) {
    return null;
  }

  return (
    getRarityDefinitionsForDevGrant().find((definition) => {
      const displayName = normalizeDevLookupText(getDevRarityDisplayName(definition));
      const typeName = normalizeDevLookupText(definition.type);
      return displayName === needle || typeName === needle;
    }) || null
  );
}

function findDevSubtitleForDefinition(definition, subtitleName) {
  if (!definition) {
    return null;
  }

  const needle = normalizeDevLookupText(subtitleName);
  if (!needle) {
    return null;
  }
  const titles = Array.isArray(definition.titles) && definition.titles.length
    ? definition.titles
    : [definition.type];

  const match = titles.find((title) => normalizeDevLookupText(title) === needle);
  if (match) {
    return match;
  }

  if (normalizeDevLookupText(definition.type) === needle) {
    return definition.type;
  }

  return String(subtitleName || "").trim() || null;
}

function getDevSubtitleCandidates(definition) {
  if (!definition) {
    return [];
  }

  const titles = Array.isArray(definition.titles) && definition.titles.length
    ? definition.titles
    : [definition.type];

  return titles
    .filter((title) => typeof title === "string" && title.trim())
    .map((title) => title.trim());
}

function getRandomDevSubtitleForDefinition(definition) {
  const titles = getDevSubtitleCandidates(definition);
  if (!titles.length) {
    return getDevRarityDisplayName(definition) || definition?.type || "";
  }

  return titles[Math.floor(Math.random() * titles.length)];
}

function grantDevTitle(titleName, subtitleName, amount) {
  const definition = findDevRarityDefinition(titleName);
  if (!definition) {
    return { ok: false, message: `Unknown title: ${titleName}` };
  }

  const hasExplicitSubtitle = typeof subtitleName === "string" && subtitleName.trim().length > 0;
  const explicitSubtitle = hasExplicitSubtitle ? findDevSubtitleForDefinition(definition, subtitleName) : null;
  if (hasExplicitSubtitle && !explicitSubtitle) {
    return { ok: false, message: `Unknown subtitle for ${getDevRarityDisplayName(definition)}.` };
  }

  const quantity = Math.max(1, Math.trunc(Number(amount)));
  if (!Number.isFinite(quantity)) {
    return { ok: false, message: "Invalid title amount." };
  }

  const rolledAt = typeof rollCount === "number" ? rollCount : 0;
  const luckValue = getCurrentLuckValue();
  const records = [];

  for (let index = 0; index < quantity; index += 1) {
    const subtitle = explicitSubtitle || getRandomDevSubtitleForDefinition(definition);
    const { record } = normalizeInventoryRecord({
      title: subtitle,
      rarityClass: definition.class,
      rolledAt,
      luckValue,
      givenByCommand: true,
    });

    if (record) {
      records.push(record);
    }
  }

  if (!records.length) {
    return { ok: false, message: "Unable to grant that title." };
  }

  inventory = [...inventory, ...records];
  storage.set("inventory", inventory);
  renderInventory();
  checkAchievements();
  updateAchievementsList();

  return {
    ok: true,
    message: hasExplicitSubtitle
      ? `Granted ${records.length.toLocaleString()} x ${explicitSubtitle}.`
      : `Granted ${records.length.toLocaleString()} random ${getDevRarityDisplayName(definition)} title${records.length === 1 ? "" : "s"}.`,
  };
}

function forceNextRollTitleCommand(titleName, subtitleName = "") {
  const definition = findDevRarityDefinition(titleName);
  if (!definition) {
    return { ok: false, message: `Unknown title: ${titleName}` };
  }

  const hasExplicitSubtitle = typeof subtitleName === "string" && subtitleName.trim().length > 0;
  const subtitle = hasExplicitSubtitle
    ? findDevSubtitleForDefinition(definition, subtitleName)
    : getRandomDevSubtitleForDefinition(definition);

  if (!subtitle) {
    return { ok: false, message: `Unknown subtitle for ${getDevRarityDisplayName(definition)}.` };
  }

  forcedNextRollTitle = {
    rarity: {
      ...definition,
      class: normalizeRarityClassName(definition.class),
      titles: [subtitle],
    },
    title: subtitle,
  };

  return {
    ok: true,
    message: `Next roll forced to ${subtitle} (${definition.type}).`,
  };
}

function findDevPotionDefinition(potionName) {
  const needle = normalizeDevLookupText(potionName);
  if (!needle) {
    return null;
  }

  return (
    POTION_DEFINITIONS.find((potion) => {
      return (
        normalizeDevLookupText(potion.id) === needle ||
        normalizeDevLookupText(potion.name) === needle
      );
    }) || null
  );
}

function grantDevPotion(potionName, amount) {
  const potion = findDevPotionDefinition(potionName);
  if (!potion) {
    return { ok: false, message: `Unknown potion: ${potionName}` };
  }

  const quantity = Math.max(1, Math.trunc(Number(amount)));
  if (!Number.isFinite(quantity)) {
    return { ok: false, message: "Invalid potion amount." };
  }

  const current = Number.isFinite(potionInventory[potion.id]) ? potionInventory[potion.id] : 0;
  potionInventory = { ...potionInventory, [potion.id]: current + quantity };
  savePotionInventory();
  renderPotionInventory();
  renderPotionCrafting();
  updateAutoRollAvailability();

  return {
    ok: true,
    message: `Granted ${quantity.toLocaleString()} x ${potion.name}.`,
  };
}

function parseDevDurationMs(parts) {
  const text = Array.isArray(parts) ? parts.join(" ") : String(parts || "");
  const source = text.trim();
  if (!source) {
    return null;
  }

  const unitMs = {
    ms: 1,
    millisecond: 1,
    milliseconds: 1,
    s: 1000,
    sec: 1000,
    secs: 1000,
    second: 1000,
    seconds: 1000,
    m: 60 * 1000,
    min: 60 * 1000,
    mins: 60 * 1000,
    minute: 60 * 1000,
    minutes: 60 * 1000,
    h: 60 * 60 * 1000,
    hr: 60 * 60 * 1000,
    hrs: 60 * 60 * 1000,
    hour: 60 * 60 * 1000,
    hours: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    day: 24 * 60 * 60 * 1000,
    days: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000,
    week: 7 * 24 * 60 * 60 * 1000,
    weeks: 7 * 24 * 60 * 60 * 1000,
    mo: 30 * 24 * 60 * 60 * 1000,
    mos: 30 * 24 * 60 * 60 * 1000,
    month: 30 * 24 * 60 * 60 * 1000,
    months: 30 * 24 * 60 * 60 * 1000,
    y: 365 * 24 * 60 * 60 * 1000,
    yr: 365 * 24 * 60 * 60 * 1000,
    yrs: 365 * 24 * 60 * 60 * 1000,
    year: 365 * 24 * 60 * 60 * 1000,
    years: 365 * 24 * 60 * 60 * 1000,
  };

  let total = 0;
  let matched = false;
  const leftovers = source.replace(/(\d+(?:\.\d+)?)\s*(milliseconds?|ms|seconds?|secs?|sec|s|minutes?|mins?|min|m|hours?|hrs?|hr|h|days?|d|weeks?|w|months?|mos?|mo|years?|yrs?|yr|y)\b/gi, (match, amount, unit) => {
    const parsedAmount = Number(amount);
    const normalizedUnit = String(unit || "").toLowerCase();
    const multiplier = unitMs[normalizedUnit];
    if (!Number.isFinite(parsedAmount) || parsedAmount <= 0 || !Number.isFinite(multiplier)) {
      return match;
    }

    matched = true;
    total += parsedAmount * multiplier;
    return " ";
  });

  if (!matched || leftovers.trim()) {
    return null;
  }

  return Number.isFinite(total) && total > 0 ? Math.round(total) : null;
}

function isDevForeverDurationParts(parts) {
  const text = Array.isArray(parts) ? parts.join(" ") : String(parts || "");
  const normalized = text.trim().toLowerCase().replace(/\s+/g, "");
  return ["forever", "infinite", "infinity", "permanent", "perm", "inf"].includes(normalized);
}

function parseDevPositiveIntegerParts(parts) {
  if (!Array.isArray(parts) || parts.length !== 1) {
    return null;
  }

  const source = String(parts[0] || "").trim().replace(/[, _]/g, "");
  if (!/^\d+$/.test(source)) {
    return null;
  }

  const parsed = Number(source);
  if (!Number.isSafeInteger(parsed) || parsed <= 0) {
    return null;
  }

  return parsed;
}

function getDevBuffReferenceTime() {
  return buffsDisabled && Number.isFinite(buffPauseStart)
    ? buffPauseStart
    : Date.now();
}

function getDevPotionCommandUses(potion) {
  if (!potion || !Number.isFinite(potion.consumeUses)) {
    return 1;
  }

  return Math.max(1, Math.trunc(potion.consumeUses));
}

function getDevPotionBuffIcon(potion) {
  return potion.buffImage || getBuffIconForType(potion.type) || potion.image;
}

function ensureDevActiveBuffForPotion(potion) {
  const referenceTime = getDevBuffReferenceTime();
  const consumeOnRoll = Boolean(potion.consumeOnRoll);
  const disableWithToggle = Object.prototype.hasOwnProperty.call(potion, "disableWithToggle")
    ? Boolean(potion.disableWithToggle)
    : null;
  const icon = getDevPotionBuffIcon(potion);

  let buff = activeBuffs.find((entry) => entry && entry.potionId === potion.id);
  if (!buff) {
    buff = {
      id: `${potion.id}-${referenceTime}-${Math.random().toString(36).slice(2, 8)}`,
      potionId: potion.id,
      type: potion.type,
      effectPercent: potion.effectPercent,
      name: potion.name,
      image: icon,
      expiresAt: referenceTime + 1,
      consumeOnRoll,
    };
    activeBuffs.push(buff);
  }

  buff.potionId = potion.id;
  buff.type = potion.type;
  buff.effectPercent = potion.effectPercent;
  buff.name = potion.name;
  buff.image = icon;
  buff.consumeOnRoll = consumeOnRoll;

  if (disableWithToggle !== null) {
    buff.disableWithToggle = disableWithToggle;
  } else if (Object.prototype.hasOwnProperty.call(buff, "disableWithToggle")) {
    delete buff.disableWithToggle;
  }

  if (!consumeOnRoll && Object.prototype.hasOwnProperty.call(buff, "usesRemaining")) {
    delete buff.usesRemaining;
  }

  return buff;
}

function grantDevBuff(potionName, valueParts) {
  const potion = findDevPotionDefinition(potionName);
  if (!potion) {
    return { ok: false, message: `Unknown potion: ${potionName}` };
  }

  const parts = Array.isArray(valueParts) ? valueParts : [];
  if (!parts.length) {
    return { ok: false, message: 'Use: giveBuff "Potion Name" Xy Xmo Xw Xd Xh Xmin Xsec/forever/<amount>' };
  }

  const consumeOnRoll = Boolean(potion.consumeOnRoll);
  const forever = isDevForeverDurationParts(parts);
  const rollAmount = consumeOnRoll ? parseDevPositiveIntegerParts(parts) : null;
  const durationMs = !forever && rollAmount === null ? parseDevDurationMs(parts) : null;

  if (!forever && rollAmount === null && (!Number.isFinite(durationMs) || durationMs <= 0)) {
    return { ok: false, message: 'Use: giveBuff "Potion Name" Xy Xmo Xw Xd Xh Xmin Xsec/forever/<amount>' };
  }

  const referenceTime = getDevBuffReferenceTime();
  const buff = ensureDevActiveBuffForPotion(potion);
  const currentExpiresAt = Number(buff.expiresAt);
  const baseExpiresAt = Number.isFinite(currentExpiresAt) && currentExpiresAt > referenceTime
    ? currentExpiresAt
    : referenceTime;

  if (forever || (consumeOnRoll && rollAmount !== null)) {
    buff.expiresAt = Number.MAX_SAFE_INTEGER;
  } else {
    const maxAdditionalDuration = Math.max(0, Number.MAX_SAFE_INTEGER - baseExpiresAt);
    buff.expiresAt = baseExpiresAt + Math.min(maxAdditionalDuration, durationMs);
  }

  let addedUses = 0;
  if (consumeOnRoll) {
    const parsedUses = Number.parseInt(buff.usesRemaining, 10);
    const currentUses = Number.isFinite(parsedUses) && parsedUses >= 1 ? parsedUses : 0;
    addedUses = forever ? Number.MAX_SAFE_INTEGER : rollAmount || getDevPotionCommandUses(potion);
    buff.usesRemaining = forever
      ? Number.MAX_SAFE_INTEGER
      : Math.min(Number.MAX_SAFE_INTEGER, currentUses + addedUses);
  }

  persistActiveBuffs();
  refreshBuffEffects();

  if (consumeOnRoll) {
    const suffix = forever || rollAmount !== null
      ? " They will not expire by time."
      : ` Expires in ${formatBuffDuration(Math.ceil(durationMs / 1000))}.`;
    return {
      ok: true,
      message: forever
        ? `Added ${potion.name} forever.`
        : `Added ${addedUses.toLocaleString()} ${potion.name} roll${addedUses === 1 ? "" : "s"}.${suffix}`,
    };
  }

  if (forever) {
    return { ok: true, message: `Added ${potion.name} forever.` };
  }

  return {
    ok: true,
    message: `Added ${formatBuffDuration(Math.ceil(durationMs / 1000))} to ${potion.name}.`,
  };
}

function grantForeverPotionBuff(potion) {
  if (!canPotionUseForeverDevButton(potion)) {
    return;
  }

  grantDevBuff(potion.name, ["forever"]);
}

function removeDevBuffCompletely(potion) {
  const before = activeBuffs.length;
  activeBuffs = activeBuffs.filter((buff) => !buff || buff.potionId !== potion.id);
  const removedCount = before - activeBuffs.length;

  if (removedCount <= 0) {
    return { ok: false, message: `${potion.name} has no active buff.` };
  }

  persistActiveBuffs();
  refreshBuffEffects();

  return { ok: true, message: `Removed ${potion.name} buff.` };
}

function removeDevBuffUses(potion, amount) {
  let remainingToRemove = amount;
  let removedUses = 0;
  let remainingUses = 0;

  activeBuffs = activeBuffs.filter((buff) => {
    if (!buff || buff.potionId !== potion.id) {
      return true;
    }

    const parsedUses = Number.parseInt(buff.usesRemaining, 10);
    const currentUses = Number.isFinite(parsedUses) && parsedUses >= 1
      ? parsedUses
      : getDevPotionCommandUses(potion);

    if (remainingToRemove >= currentUses) {
      remainingToRemove -= currentUses;
      removedUses += currentUses;
      return false;
    }

    if (remainingToRemove > 0) {
      buff.usesRemaining = currentUses - remainingToRemove;
      removedUses += remainingToRemove;
      remainingToRemove = 0;
    }

    remainingUses += Number.parseInt(buff.usesRemaining, 10) || 0;
    return true;
  });

  if (removedUses <= 0) {
    return { ok: false, message: `${potion.name} has no active buff.` };
  }

  persistActiveBuffs();
  refreshBuffEffects();

  if (remainingUses > 0) {
    return {
      ok: true,
      message: `Removed ${removedUses.toLocaleString()} ${potion.name} roll${removedUses === 1 ? "" : "s"}. Remaining: ${remainingUses.toLocaleString()}.`,
    };
  }

  return {
    ok: true,
    message: `Removed ${potion.name} buff.`,
  };
}

function removeDevBuffTime(potionName, durationParts) {
  const potion = findDevPotionDefinition(potionName);
  if (!potion) {
    return { ok: false, message: `Unknown potion: ${potionName}` };
  }

  if (isDevForeverDurationParts(durationParts)) {
    return removeDevBuffCompletely(potion);
  }

  const rollAmount = Boolean(potion.consumeOnRoll) ? parseDevPositiveIntegerParts(durationParts) : null;
  if (rollAmount !== null) {
    return removeDevBuffUses(potion, rollAmount);
  }

  const durationMs = parseDevDurationMs(durationParts);
  if (!Number.isFinite(durationMs) || durationMs <= 0) {
    return { ok: false, message: 'Use: removeBuff "Potion Name" Xy Xmo Xw Xd Xh Xmin Xsec/forever/<amount>' };
  }

  const referenceTime = getDevBuffReferenceTime();
  let removedCount = 0;
  let shortestRemainingMs = Infinity;

  activeBuffs = activeBuffs.filter((buff) => {
    if (!buff || buff.potionId !== potion.id) {
      return true;
    }

    const currentExpiresAt = Number(buff.expiresAt);
    if (!Number.isFinite(currentExpiresAt)) {
      removedCount += 1;
      return false;
    }

    const nextExpiresAt = currentExpiresAt - durationMs;
    if (nextExpiresAt <= referenceTime) {
      removedCount += 1;
      return false;
    }

    buff.expiresAt = nextExpiresAt;
    shortestRemainingMs = Math.min(shortestRemainingMs, nextExpiresAt - referenceTime);
    removedCount += 1;
    return true;
  });

  if (removedCount <= 0) {
    return { ok: false, message: `${potion.name} has no active buff.` };
  }

  persistActiveBuffs();
  refreshBuffEffects();

  if (Number.isFinite(shortestRemainingMs)) {
    return {
      ok: true,
      message: `Removed ${formatBuffDuration(Math.ceil(durationMs / 1000))} from ${potion.name}. Remaining: ${formatBuffDuration(Math.ceil(shortestRemainingMs / 1000))}.`,
    };
  }

  return {
    ok: true,
    message: `Removed ${potion.name} buff.`,
  };
}

function setDevLuckValue(value) {
  const targetLuck = Math.max(0, Number(value));
  if (!Number.isFinite(targetLuck)) {
    return { ok: false, message: "Invalid luck value." };
  }

  const baseLuck = computeLuckValueFromPercent(getActiveLuckPercentWithoutDev());
  devLuckBonusValue = targetLuck - baseLuck;
  saveDevLuckBonusValue();
  updateLuckStatDisplay();

  return {
    ok: true,
    message: `Luck set to ${getCurrentLuckValue().toLocaleString("en-US")}.`,
  };
}

function addDevLuckValue(value) {
  const delta = Number(value);
  if (!Number.isFinite(delta)) {
    return { ok: false, message: "Invalid luck amount." };
  }

  return setDevLuckValue(getCurrentLuckValue() + delta);
}

function persistRollCounts() {
  localStorage.setItem("rollCount", rollCount);
  localStorage.setItem("rollCount1", rollCount1);
}

function setDevRollCount(value) {
  const targetRolls = Math.max(0, Math.trunc(Number(value)));
  if (!Number.isFinite(targetRolls)) {
    return { ok: false, message: "Invalid roll amount." };
  }

  setRollCounts(targetRolls);
  persistRollCounts();
  updateRollDisplays();
  updateAutoRollAvailability();
  checkAchievements();
  updateAchievementsList();

  return {
    ok: true,
    message: `Rolls set to ${rollCount.toLocaleString("en-US")}.`,
  };
}

function addDevRollCount(value) {
  const delta = Math.trunc(Number(value));
  if (!Number.isFinite(delta)) {
    return { ok: false, message: "Invalid roll amount." };
  }

  return setDevRollCount(rollCount + delta);
}

function parseDevCommandLine(input) {
  const text = String(input || "").trim();
  const tokens = [];
  let current = "";
  let quote = null;
  let escaping = false;

  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];

    if (escaping) {
      current += char;
      escaping = false;
      continue;
    }

    if (char === "\\") {
      escaping = true;
      continue;
    }

    if (quote) {
      if (char === quote) {
        quote = null;
        tokens.push(current);
        current = "";
      } else {
        current += char;
      }
      continue;
    }

    if (char === "\"" || char === "'") {
      if (current) {
        return { tokens: [], error: "Put spaces between quoted values." };
      }
      quote = char;
      continue;
    }

    if (/\s/.test(char)) {
      if (current) {
        tokens.push(current);
        current = "";
      }
      continue;
    }

    current += char;
  }

  if (quote) {
    return { tokens: [], error: "Missing closing quote." };
  }

  if (escaping) {
    current += "\\";
  }

  if (current) {
    tokens.push(current);
  }

  return { tokens, error: null };
}

function splitDevCommaSeparatedGroups(input) {
  const text = String(input || "");
  const groups = [];
  let current = "";
  let quote = null;
  let escaping = false;

  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];

    if (escaping) {
      current += char;
      escaping = false;
      continue;
    }

    if (char === "\\") {
      current += char;
      escaping = true;
      continue;
    }

    if (quote) {
      current += char;
      if (char === quote) {
        quote = null;
      }
      continue;
    }

    if (char === "\"" || char === "'") {
      current += char;
      quote = char;
      continue;
    }

    if (char === ",") {
      const group = current.trim();
      if (!group) {
        return { groups: [], error: "Remove empty comma-separated entries." };
      }
      groups.push(group);
      current = "";
      continue;
    }

    current += char;
  }

  if (quote) {
    return { groups: [], error: "Missing closing quote." };
  }

  const finalGroup = current.trim();
  if (finalGroup) {
    groups.push(finalGroup);
  }

  return { groups, error: null };
}

function getDevCommandArgumentText(input) {
  const text = String(input || "").trim();
  const match = text.match(/^\S+/);
  if (!match) {
    return "";
  }

  return text.slice(match[0].length).trim();
}

function parseDevCommandArgumentGroups(input) {
  const argumentText = getDevCommandArgumentText(input);
  if (!argumentText) {
    return { groups: [], error: null };
  }

  const split = splitDevCommaSeparatedGroups(argumentText);
  if (split.error) {
    return { groups: [], error: split.error };
  }

  const groups = [];
  for (const group of split.groups) {
    const parsed = parseDevCommandLine(group);
    if (parsed.error) {
      return { groups: [], error: parsed.error };
    }
    groups.push(parsed.tokens);
  }

  return { groups, error: null };
}

function executeDevBuffGroupCommand(input, handler, usage) {
  const parsed = parseDevCommandArgumentGroups(input);
  if (parsed.error) {
    return { ok: false, message: parsed.error };
  }

  if (!parsed.groups.length) {
    return { ok: false, message: usage };
  }

  const results = [];
  for (const group of parsed.groups) {
    const [potionName, ...valueParts] = group;
    if (!potionName || !valueParts.length) {
      return { ok: false, message: usage };
    }

    results.push(handler(potionName, valueParts));
  }

  return {
    ok: results.every((result) => result.ok),
    message: results.map((result) => result.message).join(" "),
  };
}

function executeUnlockedDevCommand(input) {
  const { tokens, error } = parseDevCommandLine(input);
  if (error) {
    return { ok: false, message: error };
  }

  const [command, firstArg, secondArg, thirdArg] = tokens;
  const normalizedCommand = String(command || "").toLowerCase();

  if (normalizedCommand === "givealltitles") {
    if (tokens.length !== 1) {
      return { ok: false, message: "Use: giveAllTitles" };
    }
    const summary = grantAllDevTitlesCommand();
    return {
      ok: true,
      message: `Granted ${summary.titlesAdded.toLocaleString()} titles.`,
    };
  }

  if (normalizedCommand === "giveallachievements") {
    if (tokens.length !== 1) {
      return { ok: false, message: "Use: giveAllAchievements" };
    }
    return grantAllDevAchievementsCommand();
  }

  if (normalizedCommand === "giveachievement") {
    const achievementName = getDevAchievementArgument(tokens);
    if (!achievementName) {
      return { ok: false, message: 'Use: giveAchievement "Achievement Name"' };
    }
    return grantDevAchievementCommand(achievementName);
  }

  if (normalizedCommand === "removeachievement") {
    const achievementName = getDevAchievementArgument(tokens);
    if (!achievementName) {
      return { ok: false, message: 'Use: removeAchievement "Achievement Name"' };
    }
    return removeDevAchievementCommand(achievementName);
  }

  if (normalizedCommand === "unlimitedpotions") {
    if (tokens.length !== 1) {
      return { ok: false, message: "Use: unlimitedPotions" };
    }
    const summary = grantUnlimitedPotionsDevCommand();
    return {
      ok: true,
      message: `Unlimited potions enabled for ${summary.potionsUnlimited.toLocaleString()} potions.`,
    };
  }

  if (normalizedCommand === "givetitle" || normalizedCommand === "addtitle") {
    if (tokens.length < 3) {
      return { ok: false, message: 'Use: giveTitle "Title" ["Subtitle"] <amount>' };
    }
    const amount = tokens[tokens.length - 1];
    const subtitle = tokens.length > 3 ? tokens.slice(2, -1).join(" ") : "";
    return grantDevTitle(firstArg, subtitle, amount);
  }

  if (normalizedCommand === "forcerolltitle") {
    if (tokens.length < 2) {
      return { ok: false, message: 'Use: forceRollTitle "Title" ["Subtitle"]' };
    }
    const subtitle = tokens.length > 2 ? tokens.slice(2).join(" ") : "";
    return forceNextRollTitleCommand(firstArg, subtitle);
  }

  if (normalizedCommand === "givepotion") {
    if (tokens.length !== 3) {
      return { ok: false, message: 'Use: givePotion "Potion name" <amount>' };
    }
    return grantDevPotion(firstArg, secondArg);
  }

  if (normalizedCommand === "givebuff") {
    return executeDevBuffGroupCommand(
      input,
      grantDevBuff,
      'Use: giveBuff "Potion Name" Xy Xmo Xw Xd Xh Xmin Xsec/forever/<amount> | If multiple, seperate by commas: giveBuff "Potion Name" --||--, "Potion Name" --||--'
    );
  }

  if (normalizedCommand === "removebuff") {
    return executeDevBuffGroupCommand(
      input,
      removeDevBuffTime,
      'Use: removeBuff "Potion Name" Xy Xmo Xw Xd Xh Xmin Xsec/forever/<amount> | If multiple, seperate by commas: giveBuff "Potion Name" --||--, "Potion Name" --||--'
    );
  }

  if (normalizedCommand === "setluck") {
    if (tokens.length !== 2) {
      return { ok: false, message: "Use: setLuck <amount>" };
    }
    return setDevLuckValue(firstArg);
  }

  if (normalizedCommand === "addluck") {
    if (tokens.length !== 2) {
      return { ok: false, message: "Use: addLuck <amount>" };
    }
    return addDevLuckValue(firstArg);
  }

  if (normalizedCommand === "setrolls") {
    if (tokens.length !== 2) {
      return { ok: false, message: "Use: setRolls <amount>" };
    }
    return setDevRollCount(firstArg);
  }

  if (normalizedCommand === "addrolls") {
    if (tokens.length !== 2) {
      return { ok: false, message: "Use: addRolls <amount>" };
    }
    return addDevRollCount(firstArg);
  }

  return { ok: false, message: "Unknown dev command." };
}

function compareDevHashBytes(bytes, expected) {
  if (!Array.isArray(bytes) || !Array.isArray(expected) || bytes.length !== expected.length) {
    return false;
  }

  let mismatch = 0;
  for (let index = 0; index < expected.length; index += 1) {
    mismatch |= bytes[index] ^ expected[index];
  }

  return mismatch === 0;
}

function cryptoWordArrayToBytes(wordArray) {
  if (!wordArray || !Array.isArray(wordArray.words) || !Number.isFinite(wordArray.sigBytes)) {
    return null;
  }

  const bytes = [];
  for (let index = 0; index < wordArray.sigBytes; index += 1) {
    bytes.push((wordArray.words[index >>> 2] >>> (24 - (index % 4) * 8)) & 0xff);
  }
  return bytes;
}

async function getDevSecretHashBytes(input) {
  const text = String(input || "");

  if (
    typeof crypto !== "undefined" &&
    crypto.subtle &&
    typeof crypto.subtle.digest === "function" &&
    typeof TextEncoder !== "undefined"
  ) {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
    return Array.from(new Uint8Array(digest));
  }

  if (
    typeof CryptoJS !== "undefined" &&
    CryptoJS.SHA256 &&
    typeof CryptoJS.SHA256 === "function"
  ) {
    return cryptoWordArrayToBytes(CryptoJS.SHA256(text));
  }

  return null;
}

async function verifyDevSecret(input, expectedHash) {
  const bytes = await getDevSecretHashBytes(input);
  return compareDevHashBytes(bytes, expectedHash);
}

const DEV_COMMAND_HISTORY_KEY = "devCommandHistory";
const DEV_COMMAND_HISTORY_LIMIT = 50;

let devCommandPromptMode = "code";
let devModeEnabled = Boolean(storage.get(DEV_MODE_UNLOCKED_KEY, false));
let devCommandPromptInitialized = false;
let devCommandHistory = normalizeDevCommandHistory(storage.get(DEV_COMMAND_HISTORY_KEY, []));
let devCommandHistoryIndex = null;
let devCommandHistoryDraft = "";

function normalizeDevCommandHistory(raw) {
  if (!Array.isArray(raw)) {
    return [];
  }

  const normalized = [];
  raw.forEach((entry) => {
    const command = String(entry || "").trim();
    if (!command || normalized[normalized.length - 1] === command) {
      return;
    }
    normalized.push(command);
  });

  return normalized.slice(-DEV_COMMAND_HISTORY_LIMIT);
}

function saveDevCommandHistory() {
  devCommandHistory = normalizeDevCommandHistory(devCommandHistory);
  if (devCommandHistory.length) {
    storage.set(DEV_COMMAND_HISTORY_KEY, devCommandHistory);
  } else {
    storage.remove(DEV_COMMAND_HISTORY_KEY);
  }
}

function rememberDevCommand(command) {
  const normalized = String(command || "").trim();
  if (!normalized) {
    return;
  }

  if (devCommandHistory[devCommandHistory.length - 1] === normalized) {
    resetDevCommandHistoryNavigation();
    return;
  }

  devCommandHistory = devCommandHistory.filter((entry) => entry !== normalized);
  devCommandHistory.push(normalized);
  devCommandHistory = devCommandHistory.slice(-DEV_COMMAND_HISTORY_LIMIT);
  saveDevCommandHistory();
  resetDevCommandHistoryNavigation();
}

function resetDevCommandHistoryNavigation() {
  devCommandHistoryIndex = null;
  devCommandHistoryDraft = "";
}

function setDevCommandInputValue(input, value) {
  input.value = value;
  const cursorPosition = input.value.length;
  if (typeof input.setSelectionRange === "function") {
    input.setSelectionRange(cursorPosition, cursorPosition);
  }
}

function browseDevCommandHistory(input, direction) {
  if (!input || devCommandPromptMode !== "command" || !devModeEnabled || !devCommandHistory.length) {
    return false;
  }

  const step = direction < 0 ? -1 : 1;
  if (devCommandHistoryIndex === null) {
    if (step > 0) {
      return false;
    }
    devCommandHistoryDraft = input.value;
    devCommandHistoryIndex = devCommandHistory.length - 1;
  } else {
    devCommandHistoryIndex += step;
  }

  if (devCommandHistoryIndex < 0) {
    devCommandHistoryIndex = 0;
  }

  if (devCommandHistoryIndex >= devCommandHistory.length) {
    devCommandHistoryIndex = null;
    setDevCommandInputValue(input, devCommandHistoryDraft);
    return true;
  }

  setDevCommandInputValue(input, devCommandHistory[devCommandHistoryIndex]);
  return true;
}

function getDevCommandPromptElements() {
  return {
    prompt: byId("devCommandPrompt"),
    form: byId("devCommandPromptForm"),
    input: byId("devCommandPromptInput"),
    label: byId("devCommandPromptLabel"),
    status: byId("devCommandPromptStatus"),
  };
}

function setDevCommandPromptStatus(message, variant = "") {
  const { status } = getDevCommandPromptElements();
  if (!status) {
    return;
  }

  status.textContent = message || "";
  status.classList.toggle("dev-command-prompt__status--error", variant === "error");
  status.classList.toggle("dev-command-prompt__status--success", variant === "success");
}

function setDevCommandPromptMode(mode) {
  const { input, label } = getDevCommandPromptElements();
  devCommandPromptMode = mode;
  resetDevCommandHistoryNavigation();

  if (!input || !label) {
    return;
  }

  if (mode === "password") {
    label.textContent = "Password";
    input.type = "password";
    input.placeholder = "Enter password";
  } else if (mode === "command") {
    label.textContent = "Dev Command";
    input.type = "text";
    input.placeholder = 'addRolls 1000 / giveBuff "Lucky Potion" forever';
  } else {
    label.textContent = "Command";
    input.type = "text";
    input.placeholder = "Enter code";
  }

  input.value = "";
}

function setDevCommandPromptVisible(visible) {
  const { prompt, input } = getDevCommandPromptElements();
  if (!prompt) {
    return;
  }

  prompt.hidden = !visible;
  prompt.setAttribute("aria-hidden", visible ? "false" : "true");

  if (visible) {
    if (devModeEnabled) {
      setDevCommandPromptMode("command");
      setDevCommandPromptStatus("");
    } else {
      setDevCommandPromptMode("code");
      setDevCommandPromptStatus("");
    }
    requestAnimationFrame(() => {
      if (input && typeof input.focus === "function") {
        input.focus();
      }
    });
  }
}

function toggleDevCommandPrompt() {
  const { prompt } = getDevCommandPromptElements();
  if (!prompt) {
    return;
  }

  setDevCommandPromptVisible(prompt.hidden);
}

function isEditableDevShortcutTarget(target) {
  if (!target || !(target instanceof Element)) {
    return false;
  }

  return Boolean(
    target.closest("input, textarea, select, [contenteditable='true']")
  );
}

async function handleDevCommandPromptSubmit(event) {
  event.preventDefault();

  const { input } = getDevCommandPromptElements();
  if (!input) {
    return;
  }

  const value = input.value.trim();
  if (!value) {
    setDevCommandPromptStatus("Enter a value.", "error");
    return;
  }

  if (devCommandPromptMode === "code") {
    const ok = await verifyDevSecret(value, DEV_UNLOCK_CODE_HASH);
    if (!ok) {
      setDevCommandPromptStatus("Unknown code.", "error");
      input.value = "";
      return;
    }

    setDevCommandPromptMode("password");
    setDevCommandPromptStatus("Password required.");
    return;
  }

  if (devCommandPromptMode === "password") {
    const ok = await verifyDevSecret(value, DEV_UNLOCK_PASSWORD_HASH);
    if (!ok) {
      setDevCommandPromptStatus("Wrong password.", "error");
      input.value = "";
      return;
    }

    devModeEnabled = true;
    storage.set(DEV_MODE_UNLOCKED_KEY, true);
    renderPotionInventory();
    const summary = grantDevModeUnlockReward();
    setDevCommandPromptMode("command");
    setDevCommandPromptStatus(
      `Dev mode enabled. Commands unlocked and ${summary.rollsAdded.toLocaleString()} rolls added.`,
      "success"
    );
    return;
  }

  if (!devModeEnabled) {
    setDevCommandPromptMode("code");
    setDevCommandPromptStatus("Unlock dev mode first.", "error");
    return;
  }

  const result = executeUnlockedDevCommand(value);
  rememberDevCommand(value);
  input.value = "";
  resetDevCommandHistoryNavigation();
  setDevCommandPromptStatus(result.message, result.ok ? "success" : "error");
}

function initializeDevCommandPrompt() {
  const { form, input } = getDevCommandPromptElements();
  if (!form || !input || devCommandPromptInitialized) {
    return;
  }

  form.addEventListener("submit", (event) => {
    handleDevCommandPromptSubmit(event);
  });

  input.addEventListener("keydown", (event) => {
    if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) {
      return;
    }

    if (event.key !== "ArrowUp" && event.key !== "ArrowDown") {
      return;
    }

    const handled = browseDevCommandHistory(input, event.key === "ArrowUp" ? -1 : 1);
    if (handled) {
      event.preventDefault();
    }
  });

  input.addEventListener("input", () => {
    resetDevCommandHistoryNavigation();
  });

  document.addEventListener("keydown", (event) => {
    if (event.defaultPrevented || event.ctrlKey || event.metaKey || event.altKey) {
      return;
    }

    if (event.key === "Escape") {
      const { prompt } = getDevCommandPromptElements();
      if (prompt && !prompt.hidden) {
        event.preventDefault();
        setDevCommandPromptVisible(false);
      }
      return;
    }

    if (event.code !== "Backquote" && event.key !== "`") {
      return;
    }

    const { prompt } = getDevCommandPromptElements();
    if (!prompt || (prompt.hidden && isEditableDevShortcutTarget(event.target))) {
      return;
    }

    event.preventDefault();
    toggleDevCommandPrompt();
  });

  devCommandPromptInitialized = true;
  setDevCommandPromptMode(devModeEnabled ? "command" : "code");
  setDevCommandPromptVisible(false);
}

initializeDevCommandPrompt();

const GOODBYE_POTION_REWARDS = Object.freeze({
  fortuneSpoid1: 1000,
  fortuneSpoid2: 1000,
  fortuneSpoid3: 1000,
  hasteSpoid1: 1000,
  hasteSpoid2: 1000,
  hasteSpoid3: 1000,
});

function isGoodbyeSpoidStashClaimed() {
  return Boolean(storage.get(GOODBYE_SPOID_STASH_CLAIMED_KEY, false));
}

function grantGoodbyePotionRewards() {
  if (isGoodbyeSpoidStashClaimed()) {
    return { claimed: false, names: "" };
  }

  Object.entries(GOODBYE_POTION_REWARDS).forEach(([potionId, amount]) => {
    adjustPotionCount(potionId, amount);
  });

  renderPotionInventory();
  renderPotionCrafting();
  storage.set(GOODBYE_SPOID_STASH_CLAIMED_KEY, true);

  return {
    claimed: true,
    names: Object.keys(GOODBYE_POTION_REWARDS)
      .map((potionId) => getPotionDefinition(potionId)?.name || potionId)
      .join(", "),
  };
}

function ensureGoodbyePopup() {
  let popup = document.getElementById("goodbyePotionPopup");
  if (popup) {
    return popup;
  }

  popup = document.createElement("div");
  popup.id = "goodbyePotionPopup";
  popup.className = "goodbye-popup";
  popup.hidden = true;
  popup.setAttribute("role", "dialog");
  popup.setAttribute("aria-modal", "true");
  popup.setAttribute("aria-labelledby", "goodbyePotionTitle");
  popup.innerHTML = `
    <div class="goodbye-popup__panel" role="button" tabindex="0">
      <button class="goodbye-popup__close" type="button" aria-label="Close">Close</button>
      <p class="goodbye-popup__kicker">Goodbye</p>
      <h2 class="goodbye-popup__title" id="goodbyePotionTitle">Unnamed's RNG</h2>
      <p class="goodbye-popup__message">Click to claim the spoid stash.</p>
      <p class="goodbye-popup__status" aria-live="polite"></p>
    </div>
  `;

  const panel = popup.querySelector(".goodbye-popup__panel");
  const closeButton = popup.querySelector(".goodbye-popup__close");
  const status = popup.querySelector(".goodbye-popup__status");

  const close = () => {
    popup.hidden = true;
  };

  const claim = () => {
    if (popup.dataset.claimed === "true") {
      if (status) {
        status.textContent = "The spoid stash has already been claimed.";
      }
      return;
    }

    if (isGoodbyeSpoidStashClaimed()) {
      popup.dataset.claimed = "true";
      popup.classList.add("goodbye-popup--claimed");
      if (status) {
        status.textContent = "The spoid stash has already been claimed.";
      }
      return;
    }

    const reward = grantGoodbyePotionRewards();
    popup.dataset.claimed = "true";
    popup.classList.add("goodbye-popup--claimed");
    if (status) {
      status.textContent = reward.claimed
        ? `Added 1,000 each: ${reward.names}.`
        : "The spoid stash has already been claimed.";
    }
  };

  panel?.addEventListener("click", (event) => {
    if (event.target.closest(".goodbye-popup__close")) {
      return;
    }

    claim();
  });

  panel?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }

    event.preventDefault();
    claim();
  });

  closeButton?.addEventListener("click", close);
  popup.addEventListener("click", (event) => {
    if (event.target === popup) {
      close();
    }
  });

  document.body.appendChild(popup);
  return popup;
}

function showGoodbyePopup() {
  const popup = ensureGoodbyePopup();
  const message = popup.querySelector(".goodbye-popup__message");
  const status = popup.querySelector(".goodbye-popup__status");
  const claimed = isGoodbyeSpoidStashClaimed();
  popup.dataset.claimed = String(claimed);
  popup.classList.toggle("goodbye-popup--claimed", claimed);
  if (message) {
    message.textContent = claimed
      ? "The spoid stash has already been claimed."
      : "Click to claim the spoid stash.";
  }
  if (status) {
    status.textContent = "";
  }
  popup.hidden = false;
  popup.querySelector(".goodbye-popup__panel")?.focus();
}

function initializeVersionTitleGoodbye() {
  const title = document.querySelector(".version__title");
  if (!title || title.dataset.goodbyeInitialized === "true") {
    return;
  }

  const card = title.closest(".version__card");
  title.dataset.goodbyeInitialized = "true";
  title.tabIndex = 0;
  title.setAttribute("role", "button");
  title.setAttribute("aria-label", "Unnamed's RNG goodbye message");
  title.addEventListener("click", showGoodbyePopup);
  if (card && card.dataset.goodbyeInitialized !== "true") {
    card.dataset.goodbyeInitialized = "true";
    card.addEventListener("click", showGoodbyePopup);
  }
  title.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }

    event.preventDefault();
    showGoodbyePopup();
  });
}

initializeVersionTitleGoodbye();

function getCurrentLuckValue() {
  return computeLuckValueFromPercent(getActiveLuckPercentBreakdown().total);
}

function computeLuckValueFromPercent(totalPercent) {
  const normalizedPercent = Number.isFinite(totalPercent) ? totalPercent : 0;
  const value = 1 + normalizedPercent / 100;
  return value > 0 ? value : 0;
}

function computeLuckThreshold(permanentPercent, potionPercent) {
  const normalizedPermanent = Number.isFinite(permanentPercent)
    ? Math.max(0, permanentPercent)
    : 0;
  const normalizedPotion = Number.isFinite(potionPercent) ? Math.max(0, potionPercent) : 0;

  const totalPercent = normalizedPermanent + normalizedPotion;
  const threshold = computeLuckValueFromPercent(totalPercent);

  return threshold >= 1 ? threshold : 1;
}

function capturePendingRollLuckSnapshot(totalPercent) {
  pendingRollLuckValue = computeLuckValueFromPercent(totalPercent);
  return pendingRollLuckValue;
}

function consumePendingRollLuckSnapshot() {
  const snapshot = pendingRollLuckValue;
  pendingRollLuckValue = null;
  if (typeof snapshot === "number" && Number.isFinite(snapshot)) {
    return snapshot >= 0 ? snapshot : 0;
  }
  return null;
}

function addToInventory(title, rarityClass) {
  lastRollRarityClass = rarityClass || null;
  const commandGranted = Boolean(currentRollGrantedByCommand);
  const rolledAt = typeof rollCount === "number"
    ? rollCount
    : parseInt(localStorage.getItem("rollCount")) || 0;
  pendingAutoEquipRecord = null;
  const autoDeleteSet = getAutoDeleteSet();
  const bucket = normalizeRarityBucket(rarityClass);
  recordRarityBucketRoll(bucket);
  const pendingLuckOverride = consumePendingRollLuckSnapshot();
  if (!commandGranted && shouldSkipTitleSaveForRarityClass(rarityClass)) {
    lastRollPersisted = false;
    lastRollAutoDeleted = true;
    resumeEquippedAudioAfterCutscene = true;
    return false;
  }

  if (!commandGranted && autoDeleteSet.has(bucket)) {
    lastRollPersisted = false;
    lastRollAutoDeleted = true;
    resumeEquippedAudioAfterCutscene = true;
    return false; // not persisted
  }

  const excludedRarities = new Set(Array.from(document.querySelectorAll('.rarity-button.active')).map(btn => btn.dataset.rarity));

  if (!commandGranted) {
    for (const category in rarityCategories) {
      if (excludedRarities.has(category) && rarityCategories[category].includes(rarityClass)) {
        lastRollPersisted = false;
        lastRollAutoDeleted = true;
        resumeEquippedAudioAfterCutscene = true;
        return false;
      }
    }
  }

  const luckValue = pendingLuckOverride !== null ? pendingLuckOverride : getCurrentLuckValue();

  const { record: newRecord } = normalizeInventoryRecord({
    title,
    rarityClass,
    rolledAt,
    luckValue,
    givenByCommand: commandGranted,
  });
  if (!newRecord) {
    return false;
  }

  inventory.push(newRecord);
  storage.set("inventory", inventory);
  pendingAutoEquipRecord = newRecord;
  renderInventory();
  checkAchievements();
  updateAchievementsList();
  if (isEquinoxRarityClass(newRecord.rarityClass)) {
    setEquinoxPulseActive(true);
  }
  lastRollPersisted = true;
  lastRollAutoDeleted = false;
  return true; // persisted
}

function applyPendingAutoEquip() {
  if (!pendingAutoEquipRecord) {
    return;
  }

  const normalized = normalizeEquippedItemRecord(pendingAutoEquipRecord);
  pendingAutoEquipRecord = null;

  if (!normalized) {
    return;
  }

  if (isItemCurrentlyEquipped(normalized)) {
    return;
  }

  resumeEquippedAudioAfterCutscene = false;
  pausedEquippedAudioState = null;

  equippedItem = normalized;
  storage.set("equippedItem", normalized);
  setEquinoxPulseActive(isEquinoxRecord(normalized));
  renderInventory();
}

function displayResult(title, rarity) {
  clearCutsceneCompletionFailsafe();
  pendingCutsceneRarity = null;
  currentRollRarityForTitleSkip = null;

  const resultDiv = document.getElementById("result");
  if (!resultDiv) {
    return;
  }

  const rarityValue = rarity == null ? "" : rarity;
  const rarityText = typeof rarityValue === "string" ? rarityValue : String(rarityValue);
  const [rarityName, oddsRaw] = rarityText.split(" [");
  const odds = oddsRaw ? oddsRaw.replace(/\]$/, "") : "";
  const bucket = normalizeRarityBucket(lastRollRarityClass);
  const bucketClass = bucket ? `roll-result-card--${bucket}` : "";
  const bucketLabel = bucket ? (RARITY_BUCKET_LABELS[bucket] || bucket) : "";
  const labelClasses = getLabelClassForRarity(lastRollRarityClass, bucket);

  const card = document.createElement("div");
  card.className = "roll-result-card";
  if (bucketClass) {
    card.classList.add(bucketClass);
  }
  if (lastRollAutoDeleted) {
    card.classList.add("roll-result-card--skipped");
  }

  const header = document.createElement("div");
  header.className = "roll-result-card__header";

  const rarityLabel = document.createElement("span");
  rarityLabel.className = "roll-result-card__rarity";
  if (labelClasses.length) {
    rarityLabel.classList.add(...labelClasses);
  }
  rarityLabel.textContent = (rarityName || rarityText || "Unknown").trim();
  header.appendChild(rarityLabel);

  if (odds) {
    const oddsEl = document.createElement("span");
    oddsEl.className = "roll-result-card__odds";
    oddsEl.textContent = odds;
    header.appendChild(oddsEl);
  }

  const badge = document.createElement("span");
  badge.className = "roll-result-card__badge";
  badge.textContent = lastRollAutoDeleted ? "Skipped" : "New Title";
  header.appendChild(badge);

  const titleEl = document.createElement("div");
  titleEl.className = "roll-result-card__title";
  titleEl.textContent = title || "Unknown";

  const statusEl = document.createElement("div");
  statusEl.className = "roll-result-card__status";
  if (lastRollAutoDeleted) {
    statusEl.textContent = bucketLabel
      ? `Auto-deleted (${bucketLabel})`
      : "Auto-deleted";
    statusEl.classList.add("roll-result-card__status--skipped");
  } else {
    statusEl.textContent = "Added to inventory";
  }

  card.appendChild(header);
  card.appendChild(titleEl);
  card.appendChild(statusEl);

  resultDiv.innerHTML = "";
  resultDiv.appendChild(card);

  resumePausedEquippedAudio();

  requestAnimationFrame(() => {
    card.classList.add("is-visible");
  });
}

function recordRarityBucketRoll(bucket) {
  if (!bucket) {
    return;
  }

  if (rolledRarityBuckets.has(bucket)) {
    return;
  }

  rolledRarityBuckets.add(bucket);
  storage.set("rolledRarityBuckets", Array.from(rolledRarityBuckets));
  checkAchievements({ rarityBuckets: rolledRarityBuckets });
}

function getAutoDeleteSet() {
  return new Set(
    Array.from(document.querySelectorAll('.rarity-button.active'))
      .map(btn => btn.dataset.rarity)
  );
}

function normalizeRarityBucket(rarityClass) {
  if (!rarityClass || typeof rarityClass !== "string") return "";
  const cls = normalizeRarityClassName(rarityClass);

  const prefixMatches = [
    { prefix: "under10me", bucket: "transcendent" },
    { prefix: "under10ms", bucket: "transcendent" },
    { prefix: "under10m", bucket: "transcendent" },
    { prefix: "under1m", bucket: "under1m" },
    { prefix: "under100k", bucket: "under100k" },
    { prefix: "under10k", bucket: "under10k" },
    { prefix: "under1k", bucket: "under1k" },
    { prefix: "under100", bucket: "under100" },
  ];

  for (const { prefix, bucket } of prefixMatches) {
    if (cls.startsWith(prefix)) {
      return bucket;
    }
  }

  if (cls === "special") return "special";
  if (cls === "theDescended") return "theDescended";
  if (cls === "goodOldDays") return "goodOldDays";
  if (["under100", "under1k", "under10k", "under100k", "under1m", "transcendent", "special", "theDescended", "goodOldDays"].includes(cls)) {
    return cls;
  }

  const labelEntry = RARITY_LABEL_CLASS_MAP[cls];
  if (labelEntry) {
    const labels = Array.isArray(labelEntry) ? labelEntry : [labelEntry];
    for (const label of labels) {
      if (typeof label !== "string") {
        continue;
      }

      const normalizedLabel = label.trim();
      if (!normalizedLabel) {
        continue;
      }

      if (
        normalizedLabel.startsWith("event") ||
        normalizedLabel === "transcendent" ||
        normalizedLabel === "special" ||
        normalizedLabel === "theDescended" ||
        normalizedLabel === "goodOldDays" ||
        normalizedLabel.startsWith("under")
      ) {
        return normalizedLabel;
      }
    }
  }

  const fallbackBucket = getClassForRarity(cls);
  if (fallbackBucket) {
    return fallbackBucket;
  }


  return RARITY_CLASS_BUCKET_MAP[cls] || "";
}

function getLabelClassForRarity(rarityClass, bucket) {
  const fallback = bucket ? [bucket] : [];

  if (!rarityClass || typeof rarityClass !== "string") {
    return fallback;
  }

  const cls = rarityClass.trim();
  const mapped = RARITY_LABEL_CLASS_MAP[cls];

  if (!mapped) {
    return fallback;
  }

  if (Array.isArray(mapped)) {
    return mapped.filter(Boolean);
  }

  if (typeof mapped === "string" && mapped.trim()) {
    return mapped.trim().split(/\s+/);
  }

  return fallback;
}

function deleteByRarityBucket(bucket) {
  const before = inventory.length;

  const isLocked = (it) => {
    try {
      return typeof lockedItems === 'object' && lockedItems && lockedItems[it.title];
    } catch { return false; }
  };

  inventory = inventory.filter(it => {
    const b = normalizeRarityBucket(it.rarityClass);
    // Keep if different bucket OR locked
    return b !== bucket || isLocked(it);
  });

  if (inventory.length !== before) {
    localStorage.setItem('inventory', JSON.stringify(inventory));
    renderInventory();
  }
}

function saveToggledStates() {
  const activeRarities = Array.from(document.querySelectorAll('.rarity-button.active'))
    .map(btn => btn.dataset.rarity);
  localStorage.setItem("toggledRarities", JSON.stringify(activeRarities));
}

function loadToggledStates() {
  const savedRarities = JSON.parse(localStorage.getItem("toggledRarities")) || [];
  document.querySelectorAll(".rarity-button").forEach(button => {
    if (savedRarities.includes(button.dataset.rarity)) {
      button.classList.add("active");
    }
  });
}

function deleteAllFromInventory() {
  inventory = [];
  localStorage.setItem("inventory", JSON.stringify(inventory));
  renderInventory();
  load();
}

function deleteAllByRarity(rarityClass) {
  const lockedItems = JSON.parse(localStorage.getItem("lockedItems")) || {};
  const targetClass = normalizeRarityClassName(rarityClass);

  inventory = inventory.filter((item) => {
    return normalizeRarityClassName(item.rarityClass) !== targetClass || lockedItems[item.title] === true;
  });

  localStorage.setItem("inventory", JSON.stringify(inventory));
  renderInventory();
}

function registerInterfaceToggleButtons() {
  const toggleInventoryBtn = document.getElementById("toggleInventoryBtn");
  const inventoryCloseBtn = document.getElementById("closeInventory");
  if (toggleInventoryBtn) {
    toggleInventoryBtn.addEventListener("click", function () {
      const inventorySection = document.querySelector(".inventory");
      if (!inventorySection) {
        return;
      }

      const isVisible = inventorySection.style.visibility !== "visible";

      if (isVisible) {
        inventorySection.style.visibility = "visible";
        this.textContent = "Hide Inventory";
        document.body.classList.add("inventory-open");
      } else {
        inventorySection.style.visibility = "hidden";
        this.textContent = "Show Inventory";
        document.body.classList.remove("inventory-open");
      }
    });
  }

  if (inventoryCloseBtn) {
    inventoryCloseBtn.addEventListener("click", function () {
      const inventorySection = document.querySelector(".inventory");
      const toggleInventoryBtn = document.getElementById("toggleInventoryBtn");

      if (!inventorySection) {
        return;
      }

      inventorySection.style.visibility = "hidden";
      document.body.classList.remove("inventory-open");

      if (toggleInventoryBtn) {
        toggleInventoryBtn.textContent = "Show Inventory";
      }
    });
  }

  const toggleUiBtn = document.getElementById("toggleUiBtn");
  const uiSection = document.querySelector(".ui");

  if (toggleUiBtn && uiSection) {
    toggleUiBtn.addEventListener("click", function (event) {
      const isVisible = uiSection.style.visibility !== "hidden";

      if (isVisible) {
        uiSection.style.visibility = "hidden";
        this.textContent = "Show UI";
      } else {
        uiSection.style.visibility = "visible";
        this.textContent = "Hide UI";
      }

      if (this.textContent === "Show UI") {
        toggleUiBtn.style.display = "none";
        event.stopPropagation();
      }
    });

    document.addEventListener("click", () => {
      if (toggleUiBtn.style.display === "none") {
        toggleUiBtn.style.display = "block";
      }
    });
  }

  const toggleRollDisplayBtn = document.getElementById("toggleRollDisplayBtn");
  if (toggleRollDisplayBtn) {
    toggleRollDisplayBtn.addEventListener("click", function () {
      const inventorySection = document.querySelector(".container");
      if (!inventorySection) {
        return;
      }

      const isVisible = inventorySection.style.visibility !== "hidden";

      if (isVisible) {
        inventorySection.style.visibility = "hidden";
        rollDisplayHiddenByUser = true;
        this.textContent = "Show Roll & Display";
      } else {
        inventorySection.style.visibility = "visible";
        rollDisplayHiddenByUser = false;
        cutsceneHidRollDisplay = false;
        this.textContent = "Hide Roll & Display";
      }
    });
  }

  const toggleRollHistoryBtn = document.getElementById("toggleRollHistoryBtn");
  if (toggleRollHistoryBtn) {
    toggleRollHistoryBtn.addEventListener("click", function () {
      const historySection = document.querySelector(".historySection");
      const container = document.querySelector(".container1");
      if (!historySection || !container) {
        return;
      }

      const isVisible = historySection.style.visibility !== "hidden";

      if (isVisible) {
        historySection.style.visibility = "hidden";
        this.textContent = "Show Roll History";
        container.style.left = "10px";
      } else {
        historySection.style.visibility = "visible";
        this.textContent = "Hide Roll History";
        container.style.left = "383px";
      }
    });
  }

  const graphicsPresetContainer = document.getElementById("graphicsPresetDropdown");
  const graphicsPresetToggle = document.getElementById("graphicsPresetDropdownToggle");
  const graphicsPresetMenu = document.getElementById("graphicsPresetDropdownMenu");
  const graphicsPresetButtons = graphicsPresetMenu
    ? Array.from(graphicsPresetMenu.querySelectorAll("[data-graphics-preset]"))
    : [];

  const updateGraphicsPresetControls = () => {
    const currentPreset = getGraphicsPreset();

    if (graphicsPresetToggle) {
      let label = "Graphics Preset: Default";
      if (currentPreset === GRAPHICS_PRESETS.POTATO) {
        label = "Graphics Preset: Potato";
      } else if (currentPreset === GRAPHICS_PRESETS.REDUCED) {
        label = "Graphics Preset: Reduced";
      }
      graphicsPresetToggle.textContent = label;
    }

    graphicsPresetButtons.forEach((button) => {
      const preset = button.getAttribute("data-graphics-preset");
      const isActive = preset === currentPreset;
      button.setAttribute("aria-pressed", String(isActive));

      if (preset === GRAPHICS_PRESETS.POTATO) {
        button.textContent = isActive ? "Disable Potato Graphics" : "Potato Graphics";
      } else if (preset === GRAPHICS_PRESETS.REDUCED) {
        button.textContent = isActive ? "Restore Animations" : "Reduce Animations";
      } else {
        button.textContent = isActive ? "Default Graphics (Active)" : "Default Graphics";
      }
    });
  };

  const closeGraphicsPresetMenu = () => {
    if (!graphicsPresetMenu || !graphicsPresetToggle) {
      return;
    }

    if (!graphicsPresetMenu.hidden) {
      graphicsPresetMenu.hidden = true;
      graphicsPresetToggle.setAttribute("aria-expanded", "false");
    }
  };

  const openGraphicsPresetMenu = () => {
    if (!graphicsPresetMenu || !graphicsPresetToggle) {
      return;
    }

    graphicsPresetMenu.hidden = false;
    graphicsPresetToggle.setAttribute("aria-expanded", "true");
  };

  if (graphicsPresetToggle && graphicsPresetMenu && graphicsPresetContainer) {
    graphicsPresetToggle.addEventListener("click", () => {
      const expanded = graphicsPresetToggle.getAttribute("aria-expanded") === "true";
      if (expanded) {
        closeGraphicsPresetMenu();
      } else {
        openGraphicsPresetMenu();
      }
    });

    const handleDocumentClick = (event) => {
      if (!graphicsPresetContainer.contains(event.target)) {
        closeGraphicsPresetMenu();
      }
    };

    document.addEventListener("click", handleDocumentClick);

    const handleEscape = (event) => {
      if (event.key === "Escape") {
        if (!graphicsPresetMenu.hidden) {
          closeGraphicsPresetMenu();
        }
        graphicsPresetToggle.focus();
      }
    };

    graphicsPresetToggle.addEventListener("keydown", handleEscape);
    graphicsPresetMenu.addEventListener("keydown", handleEscape);
  }

  document.addEventListener("settingsMenuOpened", closeGraphicsPresetMenu);
  document.addEventListener("settingsMenuClosed", closeGraphicsPresetMenu);

  if (graphicsPresetButtons.length) {
    graphicsPresetButtons.forEach((button) => {
      button.addEventListener("click", () => {
        const preset = button.getAttribute("data-graphics-preset");
        const current = getGraphicsPreset();

        if (preset === GRAPHICS_PRESETS.POTATO) {
          const nextPreset =
            current === GRAPHICS_PRESETS.POTATO ? GRAPHICS_PRESETS.DEFAULT : GRAPHICS_PRESETS.POTATO;
          setGraphicsPreset(nextPreset);
        } else if (preset === GRAPHICS_PRESETS.REDUCED) {
          const nextPreset =
            current === GRAPHICS_PRESETS.REDUCED ? GRAPHICS_PRESETS.DEFAULT : GRAPHICS_PRESETS.REDUCED;
          setGraphicsPreset(nextPreset);
        } else {
          setGraphicsPreset(GRAPHICS_PRESETS.DEFAULT);
        }

        updateGraphicsPresetControls();
        closeGraphicsPresetMenu();
      });
    });
  }

  closeGraphicsPresetMenu();
  updateGraphicsPresetControls();

  const toggleBuffsSwitch = document.getElementById("toggleBuffsSwitch");
  if (toggleBuffsSwitch) {
    updateBuffsSwitchControl();
    toggleBuffsSwitch.addEventListener("change", () => {
      setBuffsDisabled(!toggleBuffsSwitch.checked);
    });
  }
}

function registerResponsiveHandlers() {
  const applyLayout = () => {
    const container = document.querySelector(".container1");
    const inventory = document.querySelector(".inventory");
    const settingsButton = document.getElementById("settingsButton");
    const achievementsButton = document.getElementById("achievementsButton");
    const statsButton = document.getElementById("statsButton");
    const sliderContainer = document.querySelector(".slider-container");
    const originalParent = document.querySelector(".original-parent");

    if (!container || !inventory || !settingsButton || !achievementsButton || !statsButton) {
      return;
    }

    if (window.innerWidth < 821) {
      container.style.left = "10px";
      inventory.style.height = "58vh";
      inventory.style.width = "42vh";

      if (sliderContainer && !container.contains(sliderContainer)) {
        container.appendChild(sliderContainer);
      }
    } else if (window.innerWidth > 821 && window.innerHeight > 1400) {
      inventory.style.width = "70vh";
      container.style.left = "383px";

      if (originalParent && sliderContainer && !originalParent.contains(sliderContainer)) {
        originalParent.appendChild(sliderContainer);
      }
    } else {
      container.style.left = "383px";
      settingsButton.style.display = "inline-block";
      achievementsButton.style.display = "inline-block";
      statsButton.style.display = "inline-block";
      inventory.style.width = "60vh";
      inventory.style.height = "85vh";

      if (originalParent && sliderContainer && !originalParent.contains(sliderContainer)) {
        originalParent.appendChild(sliderContainer);
      }
    }
  };

  applyLayout();
  window.addEventListener("resize", applyLayout);
}

function setupInventoryTabs() {
  const tabButtons = Array.from(document.querySelectorAll(".inventory-tab"));
  const panels = Array.from(document.querySelectorAll(".inventory-panel"));
  const searchContainer = document.querySelector(".inventory-search");
  const sortContainer = document.querySelector(".inventory-sort");

  if (!tabButtons.length || !panels.length) {
    return;
  }

  panels.forEach((panel, index) => {
    if (!panel.id) {
      const suffix = panel.dataset.tabPanel ? panel.dataset.tabPanel.replace(/\s+/g, "-") : String(index);
      panel.id = `inventory-panel-${suffix}`;
    }
  });

  tabButtons.forEach((button) => {
    const targetPanel = panels.find((panel) => panel.dataset.tabPanel === button.dataset.tab);
    if (targetPanel) {
      button.setAttribute("aria-controls", targetPanel.id);
    }
  });

  let activeTabName = null;

  const activateTab = (tabName) => {
    if (!tabName || tabName === activeTabName) {
      return;
    }

    activeTabName = tabName;

    const isTitlesTabActive = tabName === "titles";

    tabButtons.forEach((button) => {
      const isActive = button.dataset.tab === tabName;
      button.classList.toggle("inventory-tab--active", isActive);
      button.setAttribute("aria-selected", String(isActive));
      button.setAttribute("tabindex", isActive ? "0" : "-1");
    });

    panels.forEach((panel) => {
      const isActive = panel.dataset.tabPanel === tabName;
      panel.classList.toggle("inventory-panel--active", isActive);
      panel.setAttribute("aria-hidden", String(!isActive));
    });

    if (searchContainer) {
      searchContainer.classList.toggle("inventory-tool--hidden", !isTitlesTabActive);
      searchContainer.setAttribute("aria-hidden", String(!isTitlesTabActive));
    }

    if (sortContainer) {
      sortContainer.classList.toggle("inventory-tool--hidden", !isTitlesTabActive);
      sortContainer.setAttribute("aria-hidden", String(!isTitlesTabActive));
    }

    document.querySelectorAll(".dropdown-menu.open").forEach((menu) => {
      menu.style.display = "none";
      menu.classList.remove("open");
      const parentItem = menu.closest(".inventory-item");
      if (parentItem) {
        parentItem.classList.remove("inventory-item--menu-open");
      }
    });
  };

  tabButtons.forEach((button, index) => {
    button.addEventListener("click", () => {
      activateTab(button.dataset.tab);
    });

    button.addEventListener("keydown", (event) => {
      if (event.key !== "ArrowRight" && event.key !== "ArrowLeft") {
        return;
      }

      event.preventDefault();
      const direction = event.key === "ArrowRight" ? 1 : -1;
      const nextIndex = (index + direction + tabButtons.length) % tabButtons.length;
      const nextButton = tabButtons[nextIndex];
      if (nextButton) {
        nextButton.focus();
        activateTab(nextButton.dataset.tab);
      }
    });
  });

  const defaultTab = tabButtons.find((button) => button.classList.contains("inventory-tab--active"))
    || tabButtons[0];

  if (defaultTab) {
    activateTab(defaultTab.dataset.tab);
  }
}

